#include "Code/Sparkplug/spContactTwoBodyRowQueries.h"
#include "Analysis/PC/spContactTwoBodyRowAbi.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>

namespace
{
    using namespace sparkplug::reconstruction;
    using State = spContactTwoBodyRowStateForAnalysis;
    using Input = spContactTwoBodyRowInputForAnalysis;
    using Result = spContactTwoBodyRowResultForAnalysis;
    constexpr auto Qualified = spContactTwoBodyRowProfileForAnalysis::PcCapturedWarmFiniteNearest037F;
    static_assert(sizeof(State) == 480);
    unsigned checks = 0;
    void Check(const bool value) { ++checks; if (!value) throw std::runtime_error("Contact row contract failed"); }
    unsigned Nibble(const char c)
    {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        throw std::runtime_error("nonhex row fixture");
    }
    std::array<std::uint8_t, 480> Decode(const std::string& text)
    {
        if (text.size() != 960) throw std::runtime_error("row fixture requires480B");
        std::array<std::uint8_t, 480> bytes{};
        for (std::size_t i = 0; i != bytes.size(); ++i) bytes[i] = static_cast<std::uint8_t>((Nibble(text[i*2])<<4)|Nibble(text[i*2+1]));
        return bytes;
    }
    std::uint32_t Word(const std::uint8_t* p)
    { return std::uint32_t{p[0]} | std::uint32_t{p[1]}<<8 | std::uint32_t{p[2]}<<16 | std::uint32_t{p[3]}<<24; }
    void Put(State& state, const std::size_t offset, const std::uint32_t word)
    { for (unsigned b = 0; b != 4; ++b) state.contact[offset+b] = static_cast<std::uint8_t>(word>>(8*b)); }
    State Parse(const std::string& text)
    {
        const auto bytes = Decode(text); State state; std::copy_n(bytes.begin(), 228, state.contact.begin()); std::size_t at = 228;
        const auto array = [&bytes,&at](auto& output) { for (auto& word : output) { word=Word(bytes.data()+at); at+=4; } };
        array(state.raw6C); array(state.raw70); array(state.raw74); array(state.raw78); array(state.raw7C); array(state.raw80); array(state.raw84); return state;
    }
    std::string Hex(const State& state)
    {
        static constexpr char digits[] = "0123456789abcdef"; std::string output;
        const auto byte = [&output](const std::uint8_t value) { output.push_back(digits[value>>4]); output.push_back(digits[value&15]); };
        for (const auto value : state.contact) byte(value);
        const auto array = [&byte](const auto& words) { for (const auto word : words) for (unsigned b=0;b!=4;++b) byte(static_cast<std::uint8_t>(word>>(8*b))); };
        array(state.raw6C); array(state.raw70); array(state.raw74); array(state.raw78); array(state.raw7C); array(state.raw80); array(state.raw84); return output;
    }
    struct Example final { const char* input; const char* expected; };
    const Example Examples[] = {
        {" 3F800000 3F800000 40000000 40400000 BF800000 C0000000 C0400000 3E4CCCCD 3727C5AC", ""},
        {" 3F800000 00000000 B3800000 00000000 00000000 B3800000 00000000 3E4CCCCD 3727C5AC", ""},
        {" 3F800000 00000000 00000000 B3800000 00000000 00000000 B3800000 3E4CCCCD 3727C5AC", ""},
        {" 3F800000 B3800000 00000000 00000000 B3800000 00000000 00000000 3E4CCCCD 3727C5AC", ""},
        {" 40000000 3F800000 40000000 40400000 BF800000 C0000000 C0400000 3E4CCCCD 3727C5AC", ""},
        {" 3F000000 3F800000 40000000 40400000 BF800000 C0000000 C0400000 3E4CCCCD 3727C5AC", ""},
        {" 40400000 40000000 C0400000 40800000 C0000000 40400000 C0800000 3E4CCCCD 3727C5AC", ""},
        {" 3E800000 BF400000 3F000000 BFA00000 3F400000 BF000000 3FA00000 3E4CCCCD 3727C5AC", ""},
        {" 40800000 80000000 00000000 80000000 80000000 00000000 80000000 3E4CCCCD 3727C5AC", ""},
        {" 40800000 C1800000 41800000 C1000000 41800000 41800000 C1800000 3E4CCCCD 3727C5AC", ""},
        {" 3FA00000 3F800000 BF800001 00000000 3F800000 BF800001 80000000 3E4CCCCD 3727C5AC", ""},
        {" 3F800000 80000001 00000001 00800000 00000001 80000001 80000001 3E4CCCCD 3727C5AC", ""},
        {" 3FC00000 00000000 33800000 00000000 00000000 33800000 00000000 3E4CCCCD 3727C5AC", ""},
        {" 40400000 00000000 00000000 33800000 00000000 00000000 33800000 3E4CCCCD 3727C5AC", ""},
    };
    std::pair<State, Input> ReadInput(const std::string& line)
    {
        std::istringstream stream(line); std::string raw; Input input;
        if (!(stream >> raw >> std::hex >> input.scalarArgumentWord >> input.bodyPointWords[0] >> input.bodyPointWords[1] >> input.bodyPointWords[2] >> input.body2PointWords[0] >> input.body2PointWords[1] >> input.body2PointWords[2] >> input.managerRaw7C >> input.managerRaw80))
            throw std::runtime_error("invalid row replay input");
        std::string extra; if (stream >> extra) throw std::runtime_error("trailing row replay input");
        return {Parse(raw), input};
    }
    std::string Replay(const std::string& line)
    {
        auto [before,input] = ReadInput(line); State output;
        if (ComputeContactTwoBodyRowForAnalysis(before,input,output,Qualified) != Result::Completed)
            throw std::runtime_error("row replay was not admitted");
        return Hex(output);
    }
    void Unit()
    {
        for (const auto& example : Examples)
        {
            auto [before,input] = ReadInput(example.input); const auto original = Hex(before);
            struct Guarded final { std::array<std::uint8_t,16> left; State value; std::array<std::uint8_t,16> right; };
            Guarded output{}; output.left.fill(0xD7); output.right.fill(0xD7);
            Check(ComputeContactTwoBodyRowForAnalysis(before,input,output.value,Qualified)==Result::Completed);
            Check(Hex(output.value)==example.expected); Check(Hex(before)==original);
            Check(std::all_of(output.left.begin(),output.left.end(),[](auto x){return x==0xD7;}));
            Check(std::all_of(output.right.begin(),output.right.end(),[](auto x){return x==0xD7;}));
            auto alias=before;Check(ComputeContactTwoBodyRowForAnalysis(alias,input,alias,Qualified)==Result::Completed);Check(Hex(alias)==example.expected);
        }
        auto [before,input]=ReadInput(Examples[0].input);State output=before;const auto unchanged=Hex(output);
        Check(ComputeContactTwoBodyRowForAnalysis(before,input,output)==Result::UnqualifiedProfile);Check(Hex(output)==unchanged);
        const auto refused=[&output,&unchanged](const State& state,const Input value,const Result expected)
        { Check(ComputeContactTwoBodyRowForAnalysis(state,value,output,Qualified)==expected);Check(Hex(output)==unchanged); };
        auto changed=before;Put(changed,0,0);refused(changed,input,Result::CapturedPrimaryNotAdmitted);
        for(const auto offset:{0x40U,0x88U}){changed=before;Put(changed,offset,1);refused(changed,input,Result::FixedStateNotAdmitted);}
        changed=before;Put(changed,0x58,2);refused(changed,input,Result::FixedStateNotAdmitted);
        changed=before;Put(changed,0x88,0x100);refused(changed,input,Result::FixedStateNotAdmitted);
        for(const auto offset:{0x48U,0x4CU,0x6CU,0x70U,0x74U,0x78U,0x7CU,0x80U,0x84U}){changed=before;Put(changed,offset,0);refused(changed,input,Result::FixedStateNotAdmitted);}
        auto bad=input;bad.managerRaw7C^=1;refused(before,bad,Result::ManagerProfileNotAdmitted);
        bad=input;bad.managerRaw80^=1;refused(before,bad,Result::ManagerProfileNotAdmitted);
        for(const auto word:{0U,0x80000000U,0xBF800000U,0x3E7FFFFFU,0x40800001U,0x7F800000U,0x7FC00001U})
        {bad=input;bad.scalarArgumentWord=word;refused(before,bad,Result::OutOfDomain);}
        for(const auto offset:{0xB4U,0xB8U,0xBCU,0xC0U,0xC4U,0xC8U,0xCCU})
        {changed=before;Put(changed,offset,0x41800001U);refused(changed,input,Result::OutOfDomain);changed=before;Put(changed,offset,0x7FC00001U);refused(changed,input,Result::OutOfDomain);}
        for(unsigned lane=0;lane!=3;++lane){bad=input;bad.bodyPointWords[lane]=0xC1800001U;refused(before,bad,Result::OutOfDomain);}
        for(unsigned lane=0;lane!=3;++lane){bad=input;bad.body2PointWords[lane]=0x7FC00001U;refused(before,bad,Result::OutOfDomain);bad.body2PointWords[lane]=0xC1800001U;refused(before,bad,Result::OutOfDomain);}
        changed=before;Put(changed,0x4C,Word(changed.contact.data()+0x48));refused(changed,input,Result::FixedStateNotAdmitted);
        changed=before;Put(changed,0x70,Word(changed.contact.data()+0x6C));refused(changed,input,Result::FixedStateNotAdmitted);
        for(const auto index:{1U,2U,3U,12U,13U})
        {
            auto [state,value]=ReadInput(Examples[index].input);State result;
            Check(ComputeContactTwoBodyRowForAnalysis(state,value,result,Qualified)==Result::Completed);
            const unsigned lane=(index==2||index==13)?5:4;
            if(index==1||index==2){Check(result.raw6C[lane]==0x34800000U);Check(result.raw70[lane]==0xB4400000U);}
            if(index==3)Check(result.raw70[6]==0xB4800000U);
            if(index==12||index==13){Check(result.raw6C[lane]==0xB4800000U);Check(result.raw70[lane]==0x34400000U);}
        }
        std::cout << "ContactTwoBodyRows: " << checks << " contracts passed\n";
    }
}
int main(const int argc,char** argv)
{
    try
    {
        if(argc==2 && std::string(argv[1])=="--replay")
        {std::string line;while(std::getline(std::cin,line))if(!line.empty())std::cout<<Replay(line)<<'\n';}
        else Unit();
        return 0;
    }
    catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}
}
